// resultMessages drops the testStdOut/testStdErr messages, which echo the test output.
func resultMessages(output string) string {
	var lines []string
	for _, line := range strings.Split(output, "\n") {
		if strings.HasPrefix(line, "##teamcity[testStdOut") || strings.HasPrefix(line, "##teamcity[testStdErr") {
			continue
		}
		lines = append(lines, line)
	}
	return strings.Join(lines, "\n")
}
